window.svod_elements={lib:{},assets:[],shapes:{},setup:function(h){
const n=h.MovieClip,e=h.Container,a=h.Sprite,z=h.Text,A=h.Graphics;

// ── Таб ───────────────────────────────────────────────────────────
svod_elements.lib.Svod_tab=class extends e{
  constructor(lbl){
    super();
    this.bg=new A();this._draw(false);this.addChild(this.bg);
    const t=new z(lbl,{fontFamily:'Southbank LT',fontSize:12,fontWeight:'bold',fill:'#5a7a3a',align:'center'});
    t.anchor.set(0.5,0.5);t.x=190;t.y=18;this[t.name='lbl']=t;this.addChild(t);
    this.interactive=true;this.buttonMode=true;
    this.on('mouseover',()=>{if(!this._active)this.bg.tint=0xccddaa;});
    this.on('mouseout',()=>this.bg.tint=0xffffff);
  }
  _draw(active){
    this.bg.clear();
    if(active){this.bg.beginFill(0x1a3a0a,1);this.bg.lineStyle(1,0x4a9a1a);if(this.lbl)this.lbl.style.fill='#c8e040';}
    else{this.bg.beginFill(0x0a1608,0.9);this.bg.lineStyle(1,0x1e3c10,0.7);if(this.lbl)this.lbl.style.fill='#5a7a3a';}
    this.bg.drawRoundedRect(0,0,380,36,4);this.bg.endFill();
  }
  setActive(v){this._active=v;this._draw(v);}
};

// ── Карточка достижения ────────────────────────────────────────────
svod_elements.lib.Achiev_card=class extends e{
  constructor(){
    super();
    this.bg_mc=new A();this._drawBg(false,false);this.addChild(this.bg_mc);
    const ic=new z('',{fontFamily:'Arial',fontSize:36,align:'center'});ic.anchor.set(0.5,0.5);ic.x=40;ic.y=34;this[ic.name='icon_txt']=ic;this.addChild(ic);
    const nt=new z('',{fontFamily:'Southbank LT',fontSize:14,fontWeight:'bold',fill:'#b8d840'});nt.x=76;nt.y=10;this[nt.name='name_txt']=nt;this.addChild(nt);
    const dt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#5a7a3a',wordWrap:true,wordWrapWidth:400});dt.x=76;dt.y=30;this[dt.name='desc_txt']=dt;this.addChild(dt);
    // Прогресс
    const pbg=new A();pbg.beginFill(0x060e04,1);pbg.drawRoundedRect(0,0,430,6,2);pbg.endFill();pbg.x=76;pbg.y=52;this.addChild(pbg);
    this.prog_fill=new A();this.prog_fill.beginFill(0x50a020,1);this.prog_fill.drawRoundedRect(0,0,430,6,2);this.prog_fill.endFill();this.prog_fill.x=76;this.prog_fill.y=52;
    this[this.prog_fill.name='prog_bar']=this.prog_fill;this.addChild(this.prog_fill);
    const pt=new z('',{fontFamily:'Southbank LT',fontSize:10,fill:'#4a6a2a'});pt.x=76;pt.y=62;this[pt.name='prog_txt']=pt;this.addChild(pt);
    // Награда
    const rt=new z('',{fontFamily:'Southbank LT',fontSize:11,fill:'#c8a030'});rt.x=76;rt.y=52;rt.visible=false;this[rt.name='reward_txt']=rt;this.addChild(rt);
    // Бейдж
    const dbg=new A();dbg.beginFill(0x1a3a00,1);dbg.lineStyle(1,0x4a8a10);dbg.drawRoundedRect(0,0,80,22,3);dbg.endFill();dbg.x=76;dbg.y=6;dbg.visible=false;
    const dt2=new z('ВЫПОЛНЕНО',{fontFamily:'Southbank LT',fontSize:9,fontWeight:'bold',fill:'#80d020',align:'center'});dt2.anchor.set(0.5,0.5);dt2.x=40;dt2.y=11;
    const dw=new e();dw.addChild(dbg,dt2);dw.x=480;dw.y=10;dw.visible=false;this[dw.name='done_badge']=dw;this.addChild(dw);
  }
  _drawBg(done,locked){
    this.bg_mc.clear();
    if(done){this.bg_mc.beginFill(0x0c1e06,0.97);this.bg_mc.lineStyle(2,0x3a7018,0.8);}
    else if(locked){this.bg_mc.beginFill(0x070d04,0.7);this.bg_mc.lineStyle(1,0x111a08,0.5);}
    else{this.bg_mc.beginFill(0x080e05,0.92);this.bg_mc.lineStyle(1,0x1a3010,0.6);}
    this.bg_mc.drawRoundedRect(0,0,560,80,6);this.bg_mc.endFill();
  }
  setState(done,locked,prog,maxProg){
    this._drawBg(done,locked);
    this.done_badge.visible=done;
    this.prog_bar.visible=!done;
    this.prog_txt.visible=!done;
    if(!done){
      this.prog_bar.scale.x=Math.min(1,prog/Math.max(1,maxProg));
      this.prog_txt.text=prog+' / '+maxProg;
    }
    this.alpha=locked?0.45:1;
  }
};

// ── Плитка статистики ─────────────────────────────────────────────
svod_elements.lib.Stat_tile=class extends e{
  constructor(){
    super();
    const bg=new A();bg.beginFill(0x080e05,0.92);bg.lineStyle(1,0x1a3010,0.6);bg.drawRoundedRect(0,0,272,80,6);bg.endFill();this.addChild(bg);
    const ic=new z('',{fontFamily:'Arial',fontSize:32,align:'center'});ic.anchor.set(0.5,0.5);ic.x=44;ic.y=40;this[ic.name='icon_txt']=ic;this.addChild(ic);
    const vt=new z('',{fontFamily:'Southbank LT',fontSize:22,fontWeight:'bold',fill:'#c8e040'});vt.anchor.set(0,0.5);vt.x=86;vt.y=28;this[vt.name='val_txt']=vt;this.addChild(vt);
    const lt=new z('',{fontFamily:'Arial',fontSize:11,fill:'#4a6a2a'});lt.x=86;lt.y=50;this[lt.name='lbl_txt']=lt;this.addChild(lt);
  }
};

// ── Главное окно Сводки ────────────────────────────────────────────
svod_elements.lib.Svod_win=class extends e{
  constructor(){
    super();
    const wb=new A();wb.beginFill(0x060c04,0.97);wb.lineStyle(2,0x284a18,0.9);wb.drawRoundedRect(0,0,1200,524,6);wb.endFill();this.addChild(wb);
    const hb=new A();hb.beginFill(0x081802,1);hb.drawRect(2,2,1196,42);hb.endFill();
    const hl=new A();hl.lineStyle(1,0x284a18,0.5);hl.moveTo(2,45);hl.lineTo(1198,45);this.addChild(hb,hl);
    const ttl=new z('СВОДКА',{fontFamily:'Southbank LT',fontSize:18,fontWeight:'bold',fill:'#b8d840',letterSpacing:5,dropShadow:true,dropShadowDistance:2,dropShadowColor:'#000'});ttl.x=20;ttl.y=12;this.addChild(ttl);
    const cbg=new A();cbg.beginFill(0x3a1010,1);cbg.lineStyle(1,0x882222);cbg.drawRoundedRect(0,0,30,30,4);cbg.endFill();
    const ctx=new z('×',{fontFamily:'Arial',fontSize:22,fill:'#cc4444'});ctx.anchor.set(0.5,0.5);ctx.x=15;ctx.y=15;
    const cl=new e();cl.addChild(cbg,ctx);cl.x=1162;cl.y=7;cl.interactive=true;cl.buttonMode=true;cl.on('mouseover',()=>cbg.tint=0xddaaaa);cl.on('mouseout',()=>cbg.tint=0xffffff);
    this[cl.name='butt_close']=cl;this.addChild(cl);
    // 3 таба
    const tabs=new e();tabs.x=10;tabs.y=48;
    const tlabels=['📊 СТАТИСТИКА','🏅 ДОСТИЖЕНИЯ','🎖 ЗВАНИЯ'];
    for(let i=0;i<3;i++){
      const t=new svod_elements.lib.Svod_tab(tlabels[i]);t.x=i*(380+5);tabs['tab_'+i]=t;tabs.addChild(t);
    }
    this[tabs.name='tabs']=tabs;this.addChild(tabs);
    // Секция статистики — 8 тайлов 4×2
    const stat_s=new e();stat_s.x=10;stat_s.y=94;
    for(let i=0;i<8;i++){
      const t=new svod_elements.lib.Stat_tile();t.x=(i%4)*(272+8);t.y=Math.floor(i/4)*(80+8);
      stat_s['tile_'+i]=t;stat_s.addChild(t);
    }
    this[stat_s.name='stat_section']=stat_s;this.addChild(stat_s);
    // Секция достижений — 2 колонки × 4 карточки
    const ach_s=new e();ach_s.x=10;ach_s.y=94;ach_s.visible=false;
    for(let i=0;i<8;i++){
      const c=new svod_elements.lib.Achiev_card();c.x=(i%2)*(560+10);c.y=Math.floor(i/2)*(80+6);
      ach_s['card_'+i]=c;ach_s.addChild(c);
    }
    this[ach_s.name='ach_section']=ach_s;this.addChild(ach_s);
    // Секция званий — список
    const rank_s=new e();rank_s.x=10;rank_s.y=94;rank_s.visible=false;
    for(let i=0;i<7;i++){
      const rbg=new A();rbg.beginFill(0x080e05,0.9);rbg.lineStyle(1,0x1a3010,0.6);rbg.drawRoundedRect(0,0,1160,56,4);rbg.endFill();rbg.y=i*62;
      const ric=new z('',{fontFamily:'Arial',fontSize:30,align:'center'});ric.anchor.set(0.5,0.5);ric.x=44;ric.y=rbg.y+28;
      const rn=new z('',{fontFamily:'Southbank LT',fontSize:15,fontWeight:'bold',fill:'#b8d840'});rn.x=84;rn.y=rbg.y+8;
      const rd=new z('',{fontFamily:'Arial',fontSize:11,fill:'#5a7a3a'});rd.x=84;rd.y=rbg.y+30;
      const rbadge=new A();rbadge.beginFill(0x1a3a00,1);rbadge.lineStyle(1,0x4a8a10);rbadge.drawRoundedRect(0,0,80,22,3);rbadge.endFill();rbadge.x=1060;rbadge.y=rbg.y+17;rbadge.visible=false;
      const rbt=new z('ТЕКУЩЕЕ',{fontFamily:'Southbank LT',fontSize:9,fontWeight:'bold',fill:'#80d020',align:'center'});rbt.anchor.set(0.5,0.5);rbt.x=40;rbt.y=11;rbadge.addChild(rbt);
      rank_s['rbg_'+i]=rbg;rank_s['ric_'+i]=ric;rank_s['rn_'+i]=rn;rank_s['rd_'+i]=rd;rank_s['rbadge_'+i]=rbadge;
      rank_s.addChild(rbg,ric,rn,rd,rbadge);
    }
    this[rank_s.name='rank_section']=rank_s;this.addChild(rank_s);
  }
};

svod_elements.lib.svod_elements=class extends n{
  constructor(){super({duration:1,framerate:30});const b=new svod_elements.lib.Svod_win();this[b.name='svod_win']=b;this.addChild(b);}
};
svod_elements.stage=svod_elements.lib.svod_elements}};
